from fastapi.responses import HTMLResponse

from api.pcna import app


@app.get("/", response_class=HTMLResponse)
def home():
    return HTMLResponse(r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#073f78"><title>PCNA</title>
<style>
:root{--navy:#082f66;--blue:#075ca8;--cyan:#25afe4;--ink:#183650;--muted:#61788d;--line:#d8e4ee;--shadow:0 8px 22px rgba(8,62,112,.12)}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;background:#f7fbfe;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{min-height:100dvh}.shell{width:min(100%,620px);min-height:100dvh;margin:0 auto;background:white;padding:calc(4px + env(safe-area-inset-top)) 10px calc(72px + env(safe-area-inset-bottom));overflow-x:hidden}.head{height:54px;display:flex;align-items:center;padding-left:2px}.logo{display:block;height:48px;width:auto}.hero{height:132px;border-radius:15px;overflow:hidden;background:#063f80;box-shadow:0 5px 14px rgba(8,65,120,.14)}.hero img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 22%}.section-title{font-size:25px;line-height:1;font-weight:900;letter-spacing:-.035em;color:var(--navy);margin:10px 0 8px}.section-title:after{content:"";display:block;width:52px;height:3px;border-radius:99px;background:var(--cyan);margin-top:6px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,142px);gap:8px}.card{position:relative;overflow:hidden;border:1px solid #cfdeea;border-radius:15px;background:linear-gradient(145deg,#fff 0%,#f9fcff 100%);padding:10px 10px 9px;box-shadow:var(--shadow);cursor:pointer}.icon{position:absolute;left:10px;top:10px;width:33px;height:33px;border-radius:50%;background:var(--blue);color:#fff;display:flex;align-items:center;justify-content:center;font-size:19px;font-weight:900}.card h3{margin:46px 46px 4px 0;font-size:17px;line-height:1.04;font-weight:900;letter-spacing:-.02em;color:var(--navy)}.card p{margin:0 42px 0 0;font-size:9.5px;line-height:1.25;color:#49667f}.arrow{position:absolute;right:9px;bottom:9px;width:31px;height:31px;border-radius:50%;background:var(--blue);color:#fff;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:900}.nav{position:fixed;left:50%;transform:translateX(-50%);bottom:0;width:min(620px,100%);height:calc(62px + env(safe-area-inset-bottom));padding:3px 6px env(safe-area-inset-bottom);background:linear-gradient(90deg,#075ca8,#00356d);display:grid;grid-template-columns:repeat(5,1fr);z-index:50;box-shadow:0 -5px 18px rgba(0,48,92,.18)}.nav button{border:0;background:transparent;color:rgba(255,255,255,.72);font:inherit;font-size:10.5px;font-weight:750;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:0}.nav button.active{color:#fff;font-weight:900}.nav b{font-size:20px;line-height:1}.tool{padding:8px 2px}.back{display:inline-flex;align-items:center;gap:5px;color:var(--blue);font-weight:850;font-size:14px;margin-bottom:8px;cursor:pointer}.tool h1{font-size:28px;line-height:1.03;color:var(--navy);margin:2px 0 7px;letter-spacing:-.035em}.copy{color:var(--muted);font-size:13.5px;line-height:1.4;margin-bottom:14px}.panel{border:1px solid var(--line);border-radius:15px;padding:13px;background:#fff;box-shadow:0 4px 14px rgba(8,79,134,.05)}label{display:block;color:var(--navy);font-weight:850;font-size:12px;margin:10px 0 5px}input,textarea,.action{width:100%;font:inherit;border-radius:11px;border:1px solid #b9cbd9;background:#fff;color:#14273a;padding:12px}input{min-height:46px}textarea{min-height:100px;resize:vertical}.action{background:var(--blue);color:#fff;font-weight:850;border:none;min-height:46px;margin-top:11px;cursor:pointer}.action:disabled{opacity:.62;cursor:default}.secondary{background:#eef5fa;color:var(--blue)}.result{white-space:pre-wrap;border:1px solid var(--line);background:#fbfcfd;border-radius:13px;padding:13px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;line-height:1.45;overflow-wrap:anywhere;margin-top:11px}.matches{display:grid;gap:7px;margin-top:9px}.match{border:1px solid var(--line);border-radius:11px;padding:11px;background:#fff}.match strong{display:block;color:var(--navy)}.muted{color:var(--muted);font-size:11px}.error{background:#fff1f0;border:1px solid #f2b8b5;color:#8a1c16;padding:11px;border-radius:11px;margin-top:9px}.success{background:#eef8f1;border:1px solid #b9dec4;color:#245f36;padding:11px;border-radius:11px;margin-top:9px}
@media(min-height:800px){.hero{height:150px}.grid{grid-template-rows:repeat(2,154px)}.card h3{font-size:18px}.card p{font-size:10px}}
@media(max-height:700px){.head{height:48px}.logo{height:43px}.hero{height:112px}.section-title{font-size:22px;margin:8px 0 7px}.grid{grid-template-rows:repeat(2,128px);gap:7px}.card{padding:8px}.icon{left:8px;top:8px;width:30px;height:30px;font-size:17px}.card h3{margin-top:40px;font-size:15.5px}.card p{font-size:8.8px}.arrow{right:8px;bottom:8px;width:29px;height:29px}}
</style></head><body><main class="shell"><div id="app"></div></main>
<nav class="nav" id="nav"><button data-page="home"><b>⌂</b><span>Home</span></button><button data-page="spec"><b>✓</b><span>Specs</span></button><button data-page="search"><b>⌕</b><span>Products</span></button><button data-page="virtual"><b>◇</b><span>Virtuals</span></button><button data-page="quote"><b>$</b><span>Quotes</span></button></nav>
<script>
const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
let page=new URLSearchParams(location.search).get('page')||'home';
function setPage(p){page=p;history.pushState({},'',p==='home'?'/' : '/?page='+p);render()}
window.onpopstate=()=>{page=new URLSearchParams(location.search).get('page')||'home';render()};
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
function nav(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
function tool(title,copy,body){return `<div class="tool"><div class="back" onclick="setPage('home')">← Home</div><h1>${title}</h1><div class="copy">${copy}</div><div class="panel">${body}</div></div>`}
function home(){const cards=[['spec','✓','Spec Sample Order','Tell Nova what you need and build the verified PCNA order.'],['virtual','◇','Virtuals / Designs','Capture product and decoration direction.'],['quote','$','Quote Request','Quote a verified product and quantity.'],['projects','□','Projects','Keep customer work organized.']];return `<div class="head"><a href="https://www.pcna.com/en-us"><img class="logo" src="https://raw.githubusercontent.com/cmhart13-boop/PCNA-App/main/IMG_2337.webp" alt="PCNA"></a></div><div class="hero"><img src="https://assets.pcna.com/image/upload/ar_16:7,c_fill,g_north,pg_1,q_auto,f_jpg/Mkt_Dept/2026%20Jobs/2026-0817_Web_Messaging/0817_Web_PCNA_Hero_m.jpg" alt="PCNA lifestyle"></div><div class="section-title">What do you need?</div><div class="grid">${cards.map(x=>`<div class="card" onclick="setPage('${x[0]}')"><div class="icon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p><div class="arrow">→</div></div>`).join('')}</div>`}
async function api(params){const r=await fetch('/api/pcna?'+new URLSearchParams(params));const d=await r.json();if(!r.ok)throw new Error(d.detail||'Request failed');return d}
function searchPage(){app.innerHTML=tool('Product Search','Search the verified PCNA catalog by product name or item number.',`<label>Product name or item number</label><input id="q" placeholder="Dade Polo, Stanley 30 oz, 1603-02..."><button class="action" id="go">Search verified products</button><div id="out"></div>`);go.onclick=async()=>{try{const d=await api({action:'search',q:q.value});out.innerHTML='<div class="matches">'+d.results.map(r=>`<div class="match"><strong>${esc(r.product_name)}</strong><div>${esc(r.item_number)}</div><div class="muted">${esc([r.brand,r.color].filter(Boolean).join(' · '))}</div></div>`).join('')+'</div>'}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}}
function quotePage(){app.innerHTML=tool('Quote Request','Resolve a verified product and return its decorated USD price tier.',`<label>Product or item number</label><input id="q" placeholder="Dade Polo or TM16398"><label>Quantity</label><input id="qty" type="number" min="1" value="100"><button class="action" id="go">Build quote</button><div id="out"></div>`);go.onclick=async()=>{try{const d=await api({action:'quote',q:q.value,qty:qty.value});out.innerHTML=`<div class="result">Product: ${esc(d.product_name)}\nItem Number: ${esc(d.item_number)}\nQuantity: ${d.quantity}\nMOQ Tier: ${d.moq_tier}\nUnit Price: $${Number(d.unit_price).toFixed(2)} ${esc(d.currency)}\nSchedule: ${esc(d.schedule)}</div>`}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}}
function specPage(){app.innerHTML=tool('Spec Sample Order','Tell Nova the request in plain English. Nova interprets it, then the app resolves verified PCNA product and decoration data before building the order.',`<label>Tell Nova what you need</label><textarea id="natural" placeholder="Make me a spec sample order with the Dade Polo in black, medium, embroidery left chest, white imprint."></textarea><button class="action" id="go">Generate Spec Sample Order</button><div id="out"></div>`);go.onclick=async()=>{if(!natural.value.trim())return;const original=go.textContent;go.disabled=true;go.textContent='Nova is generating…';out.innerHTML='<div class="success">Nova is generating your verified spec sample order…</div>';try{const d=await api({action:'spec_ai',q:natural.value.trim()});out.innerHTML=`<div class="result" id="order">${esc(d.order)}</div><button class="action secondary" id="copy">Copy order</button>`;copy.onclick=()=>navigator.clipboard.writeText(d.order)}catch(e){out.innerHTML='<div class="error">'+esc(e.message)+'</div>'}finally{go.disabled=false;go.textContent=original}}}
function virtualPage(){app.innerHTML=tool('Virtuals / Designs','Capture the complete virtual request without losing product, decoration, or art direction details.',`<label>Virtual request</label><textarea id="v" placeholder="Dade Polo, black, left chest embroidery, white logo…"></textarea><button class="action" id="save">Save request</button><div id="out"></div>`);v.value=localStorage.getItem('pcna_virtual_request')||'';save.onclick=()=>{localStorage.setItem('pcna_virtual_request',v.value);out.innerHTML='<div class="success">Saved on this device.</div>'}}
function projectsPage(){const items=JSON.parse(localStorage.getItem('pcna_projects')||'[]');app.innerHTML=tool('Projects','Save lightweight customer/project notes on this device.',`<label>Project name</label><input id="pn"><label>Notes</label><textarea id="notes"></textarea><button class="action" id="save">Save project</button><div class="matches">${items.map(x=>`<div class="match"><strong>${esc(x.name||'Untitled Project')}</strong><div class="muted">${esc(x.notes||'')}</div></div>`).join('')}</div>`);save.onclick=()=>{localStorage.setItem('pcna_projects',JSON.stringify([...items,{name:pn.value,notes:notes.value}]));projectsPage()}}
function render(){nav();if(page==='search')return searchPage();if(page==='quote')return quotePage();if(page==='spec')return specPage();if(page==='virtual')return virtualPage();if(page==='projects')return projectsPage();app.innerHTML=home()}
render();
</script></body></html>''')
